import{_ as t,o as a,c as i,a2 as d}from"./chunks/framework.LX5S0jbT.js";const k=JSON.parse('{"title":"提示词模板","description":"","frontmatter":{},"headers":[],"relativePath":"zh/prompt-templates.md","filePath":"zh/prompt-templates.md"}'),s={name:"zh/prompt-templates.md"};function o(n,e,p,r,c,l){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="提示词模板" tabindex="-1">提示词模板 <a class="header-anchor" href="#提示词模板" aria-label="Permalink to &quot;提示词模板&quot;">​</a></h1><p>提示词模板（prompt template）将 Markdown 文件变成可复用的 <code>/</code> 命令。当你想复用同一段提示词，而不需要添加可执行行为或大量配套指令时，使用模板。</p><p>模板可以接受参数并出现在命令补全中。Pi 可以从个人配置、项目配置、显式路径或 Pi 包加载模板。项目配置只有在授予项目信任后才会加载。</p><h2 id="创建模板" tabindex="-1">创建模板 <a class="header-anchor" href="#创建模板" aria-label="Permalink to &quot;创建模板&quot;">​</a></h2><p>创建 <code>~/.pi/agent/prompts/review.md</code>：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Review staged git changes</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">argument-hint: &quot;[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">focus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]&quot;</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Review the staged changes. Focus on ${1:-correctness, security, and error handling}.</span></span></code></pre></div><p>文件名会成为命令名，因此这个模板可以作为 <code>/review</code> 使用。<code>description</code> 显示在命令补全中；省略时，Pi 使用第一个非空行。</p><p><code>argument-hint</code> 是可选的。必选参数用 <code>&lt;尖括号&gt;</code>，可选参数用 <code>[方括号]</code>。</p><p>在活跃会话中添加或修改模板后，运行 <code>/reload</code>。</p><p><a id="invoke-a-template"></a></p><h2 id="使用模板" tabindex="-1">使用模板 <a class="header-anchor" href="#使用模板" aria-label="Permalink to &quot;使用模板&quot;">​</a></h2><p>在编辑器中输入模板命令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/review</span></span>\n<span class="line"><span>/review concurrency</span></span></code></pre></div><p>Pi 会在结果文本进入 agent 之前展开模板。除非同名扩展命令先处理，扩展会先通过 <code>input</code> 事件收到原始输入。</p><p>模板支持以下替换：</p><table tabindex="0"><thead><tr><th>语法</th><th>结果</th></tr></thead><tbody><tr><td><code>$1</code>, <code>$2</code>, …</td><td>单个位置参数</td></tr><tr><td><code>$@</code> 或 <code>$ARGUMENTS</code></td><td>用空格连接的全部参数</td></tr><tr><td><code>${1:-default}</code></td><td>第一个参数，或默认值</td></tr><tr><td><code>${@:-default}</code></td><td>全部参数，或默认值</td></tr><tr><td><code>${@:N}</code></td><td>从位置 <code>N</code> 开始的参数</td></tr><tr><td><code>${@:N:L}</code></td><td>从位置 <code>N</code> 开始的 <code>L</code> 个参数</td></tr></tbody></table><p>参数遵循类 shell 的引号规则，因此 <code>/review &quot;API compatibility&quot;</code> 提供一个包含空格的参数。</p><p><a id="choose-where-it-loads"></a></p><h2 id="加入-pi" tabindex="-1">加入 Pi <a class="header-anchor" href="#加入-pi" aria-label="Permalink to &quot;加入 Pi&quot;">​</a></h2><p>把模板放到你的用户或项目提示词目录。约定的提示词目录只加载直接的 <code>.md</code> 子文件。</p><p>设置和包可以选择嵌套的 Markdown 文件；包清单可以通过显式路径和 glob 收窄发现范围。这些选项见<a href="./settings.html#resources">设置</a>和 <a href="./packages.html">Pi 包</a>。</p><p>项目模板在授予信任后会成为编辑器中的命令。信任一个不熟悉的项目之前，先审查其内容。参见<a href="./security.html#understand-project-trust">安全</a>。</p>',22)])])}const u=t(s,[["render",o]]);export{k as __pageData,u as default};
